package org.jlinalg.cli;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.compute.*;
import org.jlinalg.genetics.PopcornRegression;
import static org.jlinalg.cli.NextflowFiles.*;
import static org.jlinalg.cli.AllcoolsPosteriorRequest.require;
import static org.jlinalg.cli.AllcoolsPosteriorCompute.map;

/** Complete original-input capture, original compute/fit, native regression check and fresh replay. */
final class PopcornBundle {
    private PopcornBundle() { }
    static Runnable bounded(long millis,Runnable cancellation){long start=System.nanoTime();return()->{cancellation.run();if(Thread.currentThread().isInterrupted()||(System.nanoTime()-start)/1000000>millis)throw new IllegalStateException("Popcorn total wall capacity/cancellation exceeded");};}
    private static Map<Path,String> roles(PopcornRequest.Spec spec)throws IOException {
        var result=new LinkedHashMap<Path,String>();
        if(spec.compute())for(int i=0;i<2;i++){Path prefix=PopcornRuntime.absolute(list(spec.value().get("references")).get(i));var extensions=new ArrayList<>(List.of(".bed",".bim",".fam"));if(PopcornRequest.bool(spec.options().get("h2weight")))extensions.add(".h2weight");for(String ext:extensions)add(result,Path.of(prefix+ext),"population"+(i+1)+ext);}
        else add(result,PopcornRuntime.absolute(spec.value().get("score_file")),"scores.tsv");
        if(spec.fit())for(int i=0;i<2;i++)add(result,PopcornRuntime.absolute(list(spec.value().get("summaries")).get(i)),"summary"+(i+1)+".tsv");
        if(spec.value().get("extract")!=null)add(result,PopcornRuntime.absolute(spec.value().get("extract")),"extract.txt");return result;
    }
    private static void add(Map<Path,String> roles,Path path,String name)throws IOException {require(roles.putIfAbsent(path,name)==null,"Popcorn input roles must be distinct files");}
    private static Map<String,Object> effective(PopcornRequest.Spec spec){return map("compute",spec.compute(),"fit",spec.fit(),"extract",spec.value().get("extract")!=null);}
    private static Pin jsonPin(Object value)throws IOException {byte[] raw=(NextflowJson.json(value)+"\n").getBytes(StandardCharsets.UTF_8);return new Pin(raw.length,sha(raw));}
    private static void prepare(Path root,PopcornRequest.Spec spec,byte[] raw,Object inputs,Object sourceInputs,Object binding)throws IOException {
        Files.write(root.resolve("request.json"),raw,StandardOpenOption.CREATE_NEW);writeJson(root.resolve("captured-inputs.json"),inputs);writeJson(root.resolve("source-inputs.json"),sourceInputs);writeJson(root.resolve("runtime-binding.json"),binding);
        Files.writeString(root.resolve("WARNINGS.md"),PopcornRuntime.ACTION+"\n\n"+warnings(),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
        Path engine=Files.createDirectory(root.resolve("engine"));Files.createDirectory(engine.resolve("inputs"));Files.write(engine.resolve("worker.py"),PopcornRuntime.resource("worker.py"),StandardOpenOption.CREATE_NEW);writeJson(engine.resolve("effective.json"),effective(spec));writeJson(engine.resolve("profile.json"),PopcornRuntime.profile(spec.profile()));
    }
    private static Map<Path,Pin> anchors(Path root,Pin producer,byte[] raw,Object inputs,Object sourceInputs,Object binding,PopcornRequest.Spec spec)throws IOException {
        var result=new HashMap<Path,Pin>();result.put(PopcornRuntime.producerPath(),producer);result.put(root.resolve("request.json"),new Pin(raw.length,sha(raw)));result.put(root.resolve("captured-inputs.json"),jsonPin(inputs));result.put(root.resolve("source-inputs.json"),jsonPin(sourceInputs));result.put(root.resolve("runtime-binding.json"),jsonPin(binding));result.put(root.resolve("engine/effective.json"),jsonPin(effective(spec)));result.put(root.resolve("engine/profile.json"),jsonPin(PopcornRuntime.profile(spec.profile())));byte[] worker=PopcornRuntime.resource("worker.py");result.put(root.resolve("engine/worker.py"),new Pin(worker.length,sha(worker)));return result;
    }
    static Path capture(Path request,Path supplied,Runnable cancellation)throws IOException {
        PopcornRuntime.platform();if(!Files.isReadable(request))throw new PopcornRuntime.Unavailable("Popcorn analysis request unavailable: "+request);byte[] raw=bytes(request,16777216);var spec=PopcornRequest.parse(SimpleJson.parse(utf8(raw)));Runnable check=bounded(spec.wallMillis(),cancellation);Pin producer=PopcornRuntime.producer();var runtime=PopcornRuntime.open(spec.runtime(),spec.profile(),check);var roles=roles(spec);var inputs=new TreeMap<String,Object>();var sourceInputs=new ArrayList<Object>();long total=0;
        for(var entry:roles.entrySet()){Path path=entry.getKey();if(!Files.isReadable(path)||!Files.isRegularFile(path))throw new PopcornRuntime.Unavailable("Required complete permitted original Popcorn input unavailable: "+path);Pin value=pin(path,spec.inputBytes(),check);total=Math.addExact(total,value.bytes());require(total<=spec.inputBytes(),"Complete original Popcorn input byte capacity exceeded");inputs.put(entry.getValue(),map("kind","file","mode",mode(path),"bytes",value.bytes(),"sha256",value.sha256()));sourceInputs.add(map("original",path.toString(),"captured",entry.getValue(),"bytes",value.bytes(),"sha256",value.sha256()));}
        Path root=PopcornRuntime.newRoot(supplied);runtime.separate(root);for(Path path:roles.keySet())require(!root.startsWith(path)&&!path.startsWith(root),"Popcorn input/output overlap");Files.createDirectory(root);Object binding=map("path",runtime.root().toString(),"seal",runtime.seal());
        try {
            prepare(root,spec,raw,inputs,sourceInputs,binding);for(var entry:roles.entrySet()){Path target=root.resolve("engine/inputs").resolve(entry.getValue());Files.copy(entry.getKey(),target,StandardCopyOption.COPY_ATTRIBUTES);require(pin(target,spec.inputBytes(),check).equals(fingerprint(inputs.get(entry.getValue()),spec.inputBytes())),"Captured original Popcorn input changed");}
            runtime=runtime.anchored(anchors(root,producer,raw,inputs,sourceInputs,binding,spec));execute(root,spec,runtime,inputs,check);
            for(var entry:roles.entrySet())require(pin(entry.getKey(),spec.inputBytes(),check).equals(fingerprint(inputs.get(entry.getValue()),spec.inputBytes())),"Original Popcorn input changed during workflow");require(Arrays.equals(raw,bytes(request,16777216)),"Original Popcorn request changed during workflow");finish(root,spec,runtime,producer,check);return root;
        }catch(IOException|RuntimeException|Error e){failure(root,e);throw e;}
    }
    private static void immutable(Path root,PopcornRequest.Spec spec,PopcornRuntime.Context runtime,Object inputs,Runnable check)throws IOException {
        runtime.verify(check);require(NextflowJson.json(inputs).equals(NextflowJson.json(manifest(tree(root.resolve("engine/inputs"),spec.files(),spec.inputBytes(),spec.inputBytes(),check)))),"Complete captured Popcorn input population changed");
    }
    private static void execute(Path root,PopcornRequest.Spec spec,PopcornRuntime.Context runtime,Object inputs,Runnable check)throws IOException {
        immutable(root,spec,runtime,inputs,check);var command=List.of(text(runtime.value().get("python")),"-I","-B",root.resolve("engine/worker.py").toString(),root.toString(),text(runtime.value().get("source")));writeJson(root.resolve("COMMAND.json"),command);
        NextflowProcess.executeSession(command,runtime.environment(),root.resolve("process"),root,root,spec.process(),()->immutable(root,spec,runtime,inputs,check),check);
        immutable(root,spec,runtime,inputs,check);var audit=object(json(root.resolve("OUTPUT-AUDIT.json"),16777216));require(audit.get("status").equals("COMPLETE_ORIGINAL_POPCORN_ROWS")&&Boolean.FALSE.equals(audit.get("author_recipe_admitted")),"Original Popcorn complete-row audit missing");
        if(spec.fit()&&spec.options().get("estimator").equals("original-regression"))nativeCheck(root,spec,check);
        tree(root,spec.files(),spec.outputBytes(),spec.outputBytes(),check);
    }
    private static double number(Object value)throws IOException {try{return value instanceof Number n?n.doubleValue():Double.parseDouble(text(value));}catch(NumberFormatException e){throw new IOException("Invalid original numeric result",e);}}
    private static void close(Object expected,double actual)throws IOException {double e=number(expected);require(Double.isNaN(e)?Double.isNaN(actual):Double.isInfinite(e)?e==actual:Double.isFinite(actual)&&Math.abs(e-actual)<=Math.max(1e-10,Math.abs(e)*5e-9),"Native regression differs from original Popcorn: expected "+e+", found "+actual);}
    private static void nativeCheck(Path root,PopcornRequest.Spec spec,Runnable check)throws IOException {
        var capacity=object(spec.value().get("capacity"));int maxRows=(int)integer(capacity.get("rows"),2,Integer.MAX_VALUE),lineCapacity=(int)integer(capacity.get("line_characters"),256,16777216);var rows=readRows(root.resolve("engine/outputs/native-regression-rows.tsv"),maxRows,lineCapacity,check);var canonical=object(json(root.resolve("canonical.json"),268435456));int m=(int)integer(canonical.get("source_M"),2,Integer.MAX_VALUE);
        var version=spec.profile().startsWith("Popcorn-1.0-")?PopcornRegression.Version.CLI_1_0_3C21C41F:PopcornRegression.Version.CLI_1_1_20A29E8C;
        try(var context=BackendContext.select(BackendPolicy.CPU)) {
            var result=PopcornRegression.fit(rows,m,version,PopcornRequest.bool(spec.options().get("jackknife")),context.backend(),check);var values=list(canonical.get("fit"));
            for(int j=0;j<3;j++){var e=list(values.get(j));close(e.get(0),result.point().values()[j]);close(e.get(1),result.standardErrors()[j]);if(number(e.get(1))>1e-10||!Double.isFinite(number(e.get(1)))){close(e.get(2),result.sourceZ()[j]);close(e.get(3),result.sourceP()[j]);}}
            if(PopcornRequest.bool(spec.options().get("jackknife"))){var deletes=list(canonical.get("delete_values"));var pseudo=list(canonical.get("source_pseudo_values"));require(deletes.size()==result.blocks().size(),"Native/source jackknife population differs");for(int b=0;b<deletes.size();b++)for(int j=0;j<3;j++){close(list(deletes.get(b)).get(new int[]{0,2,5}[j]),result.deleteValues()[b][j]);close(list(pseudo.get(b)).get(new int[]{0,2,5}[j]),result.sourcePseudoValues()[b][j]);}}
            writeJson(root.resolve("NATIVE-REGRESSION-CHECK.json"),map("status","PASS_COMPLETE_ALIGNED_NATIVE_VS_ORIGINAL_POPCORN_REGRESSION","retained_rows",rows.size(),"original_score_M",m,"point_delete_pseudo_SE_checked",true,"absolute_tolerance",1e-10,"relative_tolerance",5e-9,"Z_P_comparison_requires_SE_above",1e-10,"score_computation_is_original_upstream",true,"whole_tool_is_native",false));
        }
    }
    static List<PopcornRegression.Row> readRows(Path path,int maxRows,int lineCapacity,Runnable check)throws IOException {
        var rows=new ArrayList<PopcornRegression.Row>();try(var in=Files.newBufferedReader(path,StandardCharsets.UTF_8)){require("N1\tN2\tZ1\tZ2\tscore1\tscore2\tscoreX".equals(line(in,lineCapacity)),"Explicit complete aligned Popcorn regression header required");String raw;while((raw=line(in,lineCapacity))!=null){check.run();require(rows.size()<maxRows,"Complete native Popcorn row capacity exceeded");String[] p=raw.split("\t",-1);require(p.length==7,"Seven literal aligned Popcorn regression columns required");try{rows.add(new PopcornRegression.Row(Double.parseDouble(p[0]),Double.parseDouble(p[1]),Double.parseDouble(p[2]),Double.parseDouble(p[3]),Double.parseDouble(p[4]),Double.parseDouble(p[5]),Double.parseDouble(p[6])));}catch(IllegalArgumentException e){throw new IOException("Invalid complete aligned Popcorn regression row "+(rows.size()+1),e);}}}return List.copyOf(rows);
    }
    private static String line(BufferedReader in,int max)throws IOException {var result=new StringBuilder();int c;while((c=in.read())!=-1){if(c=='\n')return result.toString();require(result.length()<max,"Complete native Popcorn line capacity exceeded");result.append((char)c);}return result.isEmpty()?null:result.toString();}
    private static void finish(Path root,PopcornRequest.Spec spec,PopcornRuntime.Context runtime,Pin producer,Runnable check)throws IOException {
        immutable(root,spec,runtime,json(root.resolve("captured-inputs.json"),134217728),check);require(producer.equals(PopcornRuntime.producer()),"Producing Popcorn JAR changed");writeJson(root.resolve("manifest.json"),map("schema_version",1,"profile",spec.profile(),"producer",producer,"files",manifest(tree(root,spec.files(),spec.outputBytes(),spec.outputBytes(),check)),"paper_recipe_admitted",false));writeJson(root.resolve("COMPLETED.json"),map("status","COMPLETE_SCOPED_ORIGINAL_POPCORN_WORKFLOW","manifest",pin(root.resolve("manifest.json"),16777216,check),"paper_recipe_admitted",false));
    }
    static PopcornRequest.Spec verifySaved(Path root,Runnable check)throws IOException {
        directory(root);require(!Files.exists(root.resolve("FAILURE.json"))&&!Files.exists(root.resolve("WORKER-FAILURE.json")),"Failed Popcorn attempt cannot be verified as complete");var done=object(json(root.resolve("COMPLETED.json"),1048576));keys(done,"status","manifest","paper_recipe_admitted");require(done.get("status").equals("COMPLETE_SCOPED_ORIGINAL_POPCORN_WORKFLOW")&&Boolean.FALSE.equals(done.get("paper_recipe_admitted")),"Invalid Popcorn completion scope");require(pin(root.resolve("manifest.json"),16777216,check).equals(fingerprint(done.get("manifest"),16777216)),"Saved Popcorn manifest changed");
        var saved=object(json(root.resolve("manifest.json"),16777216));keys(saved,"schema_version","profile","producer","files","paper_recipe_admitted");integer(saved.get("schema_version"),1,1);require(PopcornRuntime.producer().equals(fingerprint(saved.get("producer"),1000000000)),"Use the exact retained Popcorn producing JAR");var spec=PopcornRequest.parse(json(root.resolve("request.json"),16777216));require(spec.profile().equals(saved.get("profile"))&&Boolean.FALSE.equals(saved.get("paper_recipe_admitted")),"Saved Popcorn scope/profile changed");
        var actual=new TreeMap<>(manifest(tree(root,spec.files(),spec.outputBytes(),spec.outputBytes(),check)));actual.remove("manifest.json");actual.remove("COMPLETED.json");require(NextflowJson.json(actual).equals(NextflowJson.json(saved.get("files"))),"Complete saved Popcorn input/output/diagnostic population changed");
        var runtime=PopcornRuntime.open(spec.runtime(),spec.profile(),check);var binding=object(json(root.resolve("runtime-binding.json"),1048576));keys(binding,"path","seal");require(runtime.root().toString().equals(binding.get("path"))&&runtime.seal().equals(fingerprint(binding.get("seal"),1048576)),"Saved Popcorn runtime selection changed");var roles=roles(spec);var captured=object(json(root.resolve("captured-inputs.json"),134217728));require(new HashSet<>(roles.values()).equals(captured.keySet()),"Saved Popcorn complete input roles differ");return spec;
    }
    static void verify(Path original,Path supplied,Runnable cancellation)throws IOException {
        PopcornRuntime.platform();original=original.toAbsolutePath().normalize();var spec=verifySaved(original,cancellation);Runnable check=bounded(spec.wallMillis(),cancellation);var runtime=PopcornRuntime.open(spec.runtime(),spec.profile(),check);Path root=PopcornRuntime.newRoot(supplied);runtime.separate(root);require(!root.startsWith(original)&&!original.startsWith(root),"Replay overlaps saved Popcorn evidence");Files.createDirectory(root);
        try {
            byte[] raw=bytes(original.resolve("request.json"),16777216);Object inputs=json(original.resolve("captured-inputs.json"),134217728),sourceInputs=json(original.resolve("source-inputs.json"),134217728),binding=json(original.resolve("runtime-binding.json"),1048576);prepare(root,spec,raw,inputs,sourceInputs,binding);
            for(Object item:object(inputs).keySet()){String name=member(text(item));Files.copy(original.resolve("engine/inputs").resolve(name),root.resolve("engine/inputs").resolve(name),StandardCopyOption.COPY_ATTRIBUTES);}
            runtime=runtime.anchored(anchors(root,PopcornRuntime.producer(),raw,inputs,sourceInputs,binding,spec));execute(root,spec,runtime,inputs,check);require(NextflowJson.json(json(original.resolve("canonical.json"),268435456)).equals(NextflowJson.json(json(root.resolve("canonical.json"),268435456))),"Fresh original Popcorn replay differs in complete score/aligned/fit/jackknife populations");
            verifySaved(original,check);writeJson(root.resolve("REPLAY.json"),map("status","PASS_COMPLETE_FRESH_POPCORN_REPLAY","original_completion",pin(original.resolve("COMPLETED.json"),1048576,check),"all_canonical_rows_equal",true,"paper_recipe_admitted",false));finish(root,spec,runtime,PopcornRuntime.producer(),check);verifySaved(original,check);
        }catch(IOException|RuntimeException|Error e){failure(root,e);throw e;}
    }
    private static void failure(Path root,Throwable error)throws IOException {Files.deleteIfExists(root.resolve("COMPLETED.json"));writeJson(root.resolve("FAILURE.json"),map("status",error instanceof PopcornRuntime.Unavailable||error instanceof NextflowProcess.Unavailable?"SKIP3_DEPENDENT_POPCORN_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_POPCORN_WORKFLOW","error",error.toString(),"required_action",PopcornRuntime.ACTION,"analysis_admitted",false));}
    private static String warnings(){return "Original two-population compute/fit uses explicit genetic-effect or genetic-impact mode. Full native aligned-row regression is checked against original default WLS; PLINK score computation, allele harmonization and optional MLE use unmodified upstream source. Reference compute requires one chromosome, strictly ordered distinct BP and consistent shared SNP order/coordinates across panels because the original independently sorts indices and does not separate chromosomes in its window scan. Prepare and document actual reference panels; no silent reordering/identifier repair occurs. Precomputed ten-column scores can cover multiple chromosomes and require an honest explicit mode/provenance declaration. Native limits do not reserve JVM memory. Original negative/nonfinite estimates or undefined/zero requested uncertainty retain diagnostics and fail complete-result admission. No-jackknife mode admits point estimates only. Regression rho outside [-1,1] is retained with a warning, without clipping. The source tests rho=1 and uses its original reverse-sign jackknife pseudovalues. Single-population, overlap, hidden region-fit, liability, likelihood plotting and author recipes are outside this workflow scope.\n";}
}
